const SHELL = 'mast-shell-' + VERSION, RT = 'mast-rt-v1';

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(SHELL);
    await Promise.all(PRECACHE.map(async u => { try { const r = await fetch(new Request(u, { cache: 'reload' })); if (r.ok) await c.put(u, r); } catch (_) { } }));
    // do not skipWaiting: the page offers "New version ready - Refresh"
  })());
});
self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('mast-shell-') && k !== SHELL) await caches.delete(k);
    await self.clients.claim();
  })());
});
let warming = false;
async function warm() {
  if (warming) return; warming = true; const c = await caches.open(SHELL);
  for (const u of WARM) { try { if (await c.match(u)) continue; const r = await fetch(u); if (r.ok) await c.put(u, r); } catch (_) { } }
}
self.addEventListener('message', e => { if (e.data === 'skip') self.skipWaiting(); else if (e.data === 'warm') e.waitUntil(warm()); });

const scope = new URL(self.registration.scope);
const rel = u => u.pathname.slice(scope.pathname.length);

async function swr(req) {
  const c = await caches.open(SHELL), hit = await c.match(req, { ignoreSearch: true });
  const net = fetch(req).then(r => { if (r.ok) c.put(req, r.clone()); return r; }).catch(() => null);
  return hit || (await net) || new Response('', { status: 504 });
}
async function cacheFirst(req, name) {
  const hit = await caches.match(req, { ignoreSearch: true }); if (hit) return hit;
  const r = await fetch(req); if (r.ok) (await caches.open(name)).put(req, r.clone()); return r;
}
self.addEventListener('fetch', e => {
  const req = e.request, u = new URL(req.url);
  if (req.method !== 'GET' || u.origin !== location.origin || !u.pathname.startsWith(scope.pathname)) return; // chess.com, Anthropic etc go straight to the network
  const p = rel(u);
  if (req.mode === 'navigate') { e.respondWith(caches.match('index.html', { cacheName: SHELL }).then(r => r || fetch(req))); return; }
  if (p.endsWith('.mp4')) return; // ad videos: plain network (range requests, never cached)
  if (p.startsWith('vendor/stockfish/')) { e.respondWith(cacheFirst(req, RT)); return; }
  if (/^data\/.*\.json$/.test(p)) { e.respondWith(swr(req)); return; }
  e.respondWith(cacheFirst(req, RT));
});
